import assert from 'node:assert/strict';
import { readFileSync, writeFileSync } from 'node:fs';
// Twitch's Get Started (https://dev.twitch.tv/docs/api/get-started/): an app access token from the client credentials
// grant, validated, then the channel this app streams to read through Get Users, Get Channel Information and Get Streams.
const clientId = process.env.TWITCH_CLIENT_ID;
const clientSecret = process.env.TWITCH_CLIENT_SECRET;
const channel = process.env.TWITCH_CHANNEL;
assert.ok(clientId && clientSecret && channel, 'TWITCH_CLIENT_ID, TWITCH_CLIENT_SECRET and TWITCH_CHANNEL are set');
const receipt = 'twitch-records.json';
async function helix(path, token) {
  const res = await fetch(`https://api.twitch.tv/helix${path}`, { headers: { authorization: `Bearer ${token}`, 'client-id': clientId } });
  const body = await res.json();
  assert.equal(res.status, 200, `${path}: ${res.status} ${JSON.stringify(body)}`);
  return body;
}
if (process.argv[2] === 'readback') {
  const saved = JSON.parse(readFileSync(receipt, 'utf8'));
  const users = await helix(`/users?login=${encodeURIComponent(channel)}`, saved.token);
  assert.equal(users.data.length, 1);
  assert.equal(users.data[0].id, saved.user);
  assert.equal(users.data[0].login, channel);
  const channels = await helix(`/channels?broadcaster_id=${saved.user}`, saved.token);
  assert.equal(channels.data[0].broadcaster_login, channel);
  console.log(JSON.stringify({ retained: true, user: saved.user, login: channel }));
} else {
  const granted = await fetch('https://id.twitch.tv/oauth2/token', {
    method: 'POST', headers: { 'content-type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ client_id: clientId, client_secret: clientSecret, grant_type: 'client_credentials' }),
  });
  const token = await granted.json();
  assert.equal(granted.status, 200, JSON.stringify(token));
  assert.equal(token.token_type, 'bearer');
  assert.match(token.access_token, /^[a-z0-9]{30}$/);
  assert.ok(token.expires_in > 0);
  const validated = await fetch('https://id.twitch.tv/oauth2/validate', { headers: { authorization: `OAuth ${token.access_token}` } });
  const valid = await validated.json();
  assert.equal(validated.status, 200, JSON.stringify(valid));
  assert.equal(valid.client_id, clientId);
  assert.equal(valid.login, null);
  assert.equal(valid.user_id, null);
  const users = await helix(`/users?login=${encodeURIComponent(channel)}`, token.access_token);
  assert.equal(users.data.length, 1);
  const user = users.data[0];
  assert.equal(user.login, channel);
  assert.match(user.id, /^\d+$/);
  assert.equal('email' in user, false);
  const channels = await helix(`/channels?broadcaster_id=${user.id}`, token.access_token);
  assert.equal(channels.data[0].broadcaster_id, user.id);
  assert.equal(channels.data[0].broadcaster_login, channel);
  const streams = await helix(`/streams?user_login=${encodeURIComponent(channel)}`, token.access_token);
  assert.deepEqual(streams.data, []);
  writeFileSync(receipt, `${JSON.stringify({ token: token.access_token, user: user.id })}\n`);
  console.log(JSON.stringify({ token: 'app access token', user: user.id, login: user.login, title: channels.data[0].title, live: streams.data.length > 0 }));
}
